script:
var STEPS = {{steps}};
var RATE = {{rate}};

var curvePath = document.getElementById('curve');
var ball = document.getElementById('ball');
var tangent = document.getElementById('tangent');
var caption = document.getElementById('caption');
var status = document.getElementById('status');

var LEFT = 30;
var RIGHT = 440;
var TOP = 20;
var BOTTOM = 180;

// 一个教学用的损失函数：L(w) = 0.8 * (w - 3)^2 + 0.4（最低点在 w = 3）
var W_MIN = -3;
var W_MAX = 9;
var BEST_W = 3;

function loss(w) {
  return 0.8 * (w - BEST_W) * (w - BEST_W) + 0.4;
}

function lossGradient(w) {
  return 1.6 * (w - BEST_W);
}

var MAX_LOSS = loss(W_MIN) > loss(W_MAX) ? loss(W_MIN) : loss(W_MAX);

function toX(w) {
  return LEFT + ((w - W_MIN) / (W_MAX - W_MIN)) * (RIGHT - LEFT);
}

function toY(value) {
  return BOTTOM - (value / MAX_LOSS) * (BOTTOM - TOP);
}

var points = [];
for (var w = W_MIN; w <= W_MAX + 0.0001; w += 0.08) {
  points.push(toX(w).toFixed(1) + ',' + toY(loss(w)).toFixed(1));
}
curvePath.setAttribute('d', 'M' + points.join(' L'));

// 参数轨迹：从 w = -2 出发，按「负梯度方向」一步步走
var trail = [-2];
for (var step = 0; step < STEPS; step += 1) {
  var current = trail[trail.length - 1];
  var next = current - RATE * lossGradient(current);
  if (next > W_MAX) next = W_MAX;
  if (next < W_MIN) next = W_MIN;
  trail.push(next);
}

// ★ 播放前先把球放到起点（实测缺陷）：`circle` 不写 cx/cy 时默认就是 (0,0)，
//   而 (0,0) 在 viewBox 之外 —— 学生一进来就先看到左上角冒出一个被裁掉一半的橙点。
//   这里只是把「第一步要画到哪」提前落定，动画本身一个字节没动。
ball.setAttribute('cx', String(toX(trail[0])));
ball.setAttribute('cy', String(toY(loss(trail[0]))));

function moveBall(w, duration) {
  return {
    targets: ball,
    cx: toX(w),
    cy: toY(loss(w)),
    duration: duration,
    easing: 'easeInOutQuad'
  };
}

function showTangent(w) {
  var slope = lossGradient(w);
  var span = 1.2;
  var x1 = toX(w - span);
  var y1 = toY(loss(w - span));
  var x2 = toX(w + span);
  var y2 = toY(loss(w + span));
  // 斜率方向用切线斜率体现（视觉上足够示意「往哪边下坡」）
  tangent.setAttribute('x1', String(x1));
  tangent.setAttribute('y1', String(y1 - slope * 6));
  tangent.setAttribute('x2', String(x2));
  tangent.setAttribute('y2', String(y2 + slope * 6));
  tangent.setAttribute('opacity', '1');
}

Sandbox.play(function () {
  var steps = [];
  steps.push({
    ...moveBall(trail[0], 1),
    begin: function () {
      ball.setAttribute('cx', String(toX(trail[0])));
      ball.setAttribute('cy', String(toY(loss(trail[0]))));
      caption.textContent = '我们随便从 w = ' + trail[0].toFixed(2) + ' 出发，此时损失是 ' + loss(trail[0]).toFixed(2) + '。';
      status.textContent = '损失 ' + loss(trail[0]).toFixed(2);
      showTangent(trail[0]);
    },
    complete: function () {
      tangent.setAttribute('opacity', '0');
    }
  });

  for (var i = 1; i < trail.length; i += 1) {
    var w = trail[i];
    var previous = trail[i - 1];
    steps.push({
      ...moveBall(w, 420),
      begin: (function (index, cur, prev) {
        return function () {
          showTangent(prev);
          var direction = lossGradient(prev) > 0 ? '下降' : '上升';
          caption.textContent =
            '第 ' + index + ' 步：梯度是 ' + lossGradient(prev).toFixed(2) + '（损失正在' + direction + '），' +
            '所以把 w 往反方向挪一点 → w = ' + cur.toFixed(2) + '。';
          status.textContent = '损失 ' + loss(cur).toFixed(2);
        };
      })(i, w, previous),
      complete: (function (cur) {
        return function () {
          tangent.setAttribute('opacity', '0');
          Sandbox.progress(trail.indexOf(cur) / (trail.length - 1));
        };
      })(w)
    });
  }

  var last = trail[trail.length - 1];
  steps.push({
    targets: ball,
    r: [9, 12],
    duration: 260,
    direction: 'alternate',
    begin: function () {
      caption.textContent =
        '停了：w ≈ ' + last.toFixed(2) + '（真正的答案是 ' + BEST_W + '），损失从 ' +
        loss(trail[0]).toFixed(2) + ' 降到 ' + loss(last).toFixed(2) + '。学习率越大走得越快，但太大就会来回震荡。';
      status.textContent = '最终损失 ' + loss(last).toFixed(2);
    }
  });

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutQuad' });
  for (var s = 0; s < steps.length; s += 1) timeline.add(steps[s]);
  timeline.play();

  var total = timeline.duration || 6000;
  return {
    pause: function () { timeline.pause(); },
    play: function () { timeline.play(); },
    restart: function () { timeline.restart(); },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > total + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / total));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'gradient-descent', steps: STEPS });
